// ---------------------------------------------------------------------------
// DA Form 2408-20 (Oil Analysis Log) — AcroForm named-field path.
//
// Unlike the original pdfgen-vanilla POC (which used this form to prove out
// the *coordinate*-fill path against a flattened copy), this multi-form-type
// slice uses only the AcroForm path for every form type, so this file uses
// the PDF's original, unflattened AcroForm fields instead.
//
// Field names were confirmed with pdf-lib against reference-acroform/
// A2408_20.pdf: each named field's widget rectangle was cross-checked
// against the real coordinates already validated in the original POC's
// coordinate-fill field map (HEADER_FIELDS/ROW_COLS/PAGE1_ROW_Y/PAGE2_ROW_Y)
// — every field's (x, y) matched exactly, confirming the mapping below.
// Row fields follow the same LiveCycle naming quirk as 2408-18: base name
// for row 0, "<base>_N" for row N, and the back page reuses different base
// names for the same visual columns (e.g. "COMP" front / "COMP_A" back).
// ---------------------------------------------------------------------------
const ACROFORM_2408_20_B64 = "";

function emptyRow2408_20() {
  return {
    id: uid(),
    dateSampleSubmitted: "", hoursEndItem: "", hoursComponent: "", hoursLastOilChange: "",
    reasonForSample: "", results: "", resultsDate: "", resultsPid: "",
  };
}

function emptyForm2408_20() {
  return {
    id: uid(),
    header: {
      endItemNomenclature: "", endItemMakeOrType: "", endItemSerialNumber: "",
      sampleFrequency: "",
      componentNomenclatureType: "", componentSerialNumber: "", componentTimeSinceNewOverhaul: "",
      acftHrsLastOilChange: "", acftHrsInstalled: "",
      remarks: "",
    },
    rows: [emptyRow2408_20()],
  };
}

function cloneForm2408_20(form) {
  return {
    id: uid(),
    header: { ...form.header },
    rows: form.rows.map(r => ({ ...r, id: uid() })),
  };
}

function copies2408_20(form, styles) {
  return buildAcroFormCopies(ACROFORM_2408_20_B64, form, {
    root: "topmostSubform",
    page1Rows: 12,
    page2Rows: 8,
    repeatingHeaderExclude: ["remarks"], // remarks lives on page 2 of copy 1 only
    header: {
      page:                          "topmostSubform[0].Page1[0].Page[0]",
      pageOf:                        "topmostSubform[0].Page1[0].Pageof[0]",
      endItemNomenclature:           "topmostSubform[0].Page1[0].Nomen[0]",
      endItemMakeOrType:             "topmostSubform[0].Page1[0].Make[0]",
      endItemSerialNumber:           "topmostSubform[0].Page1[0].SerNoA[0]",
      sampleFrequency:               "topmostSubform[0].Page1[0].Frequency[0]",
      componentNomenclatureType:     "topmostSubform[0].Page1[0].Type[0]",
      componentSerialNumber:         "topmostSubform[0].Page1[0].SerNo[0]",
      componentTimeSinceNewOverhaul: "topmostSubform[0].Page1[0].Time[0]",
      acftHrsLastOilChange:          "topmostSubform[0].Page1[0].AcftHrsOil[0]",
      acftHrsInstalled:              "topmostSubform[0].Page1[0].AcftHrs[0]",
      remarks:                       "topmostSubform[0].Page2[0].Remarks[0]",
    },
    cols: [
      { key: "dateSampleSubmitted", p1: "Date",      p2: "DateB"    },
      { key: "hoursEndItem",        p1: "EndItem",   p2: "EndItemB" },
      { key: "hoursComponent",      p1: "COMP",      p2: "COMP_A"   },
      { key: "hoursLastOilChange",  p1: "OilChange", p2: "LastOilB" },
      { key: "reasonForSample",     p1: "Reason",    p2: "ReasonB"  },
      { key: "results",             p1: "Results",   p2: "ResultsB" },
      { key: "resultsDate",         p1: "DateA",      p2: "DateC"   },
      { key: "resultsPid",          p1: "PID",        p2: "PIDB"    },
    ],
  }, styles);
}

// Single-instance "Print Preview" path: fill this instance's copies, then
// merge them (if more than one) into one interactive AcroForm PDF. "Print
// All" instead calls copies2408_20 directly and merges across every
// instance/type in one pass — see buildCombinedPdf in index.html.
async function buildFilledPdf2408_20(form, styles) {
  const outDoc = await mergeAcroFormDocs(await copies2408_20(form, styles));
  return outDoc.save();
}

